CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE TABLE admins (id uuid PRIMARY KEY, email text UNIQUE NOT NULL, password_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions (token_hash text PRIMARY KEY, admin_id uuid NOT NULL REFERENCES admins(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL);
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE brands (id text PRIMARY KEY, name text NOT NULL, slug text UNIQUE NOT NULL, document jsonb NOT NULL);
CREATE UNIQUE INDEX brands_name_unique ON brands(lower(name));
CREATE TABLE categories (id text PRIMARY KEY, name text NOT NULL, slug text UNIQUE NOT NULL, parent_id text REFERENCES categories(id) ON DELETE RESTRICT, document jsonb NOT NULL, CHECK(parent_id IS DISTINCT FROM id));
CREATE INDEX categories_parent ON categories(parent_id);
CREATE UNIQUE INDEX categories_name_unique ON categories(lower(name));
CREATE TABLE products (id text PRIMARY KEY, slug text UNIQUE NOT NULL, name text NOT NULL, brand_id text REFERENCES brands(id) ON DELETE RESTRICT, status text NOT NULL CHECK(status IN ('draft','active','out-of-stock')), price bigint NOT NULL CHECK(price>=0), stock integer NOT NULL CHECK(stock>=0), document jsonb NOT NULL, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX products_status_created ON products(status,created_at DESC,id);
CREATE INDEX products_brand ON products(brand_id);
CREATE INDEX products_search ON products USING gin(name gin_trgm_ops);
CREATE INDEX products_price ON products(status,price);
CREATE TABLE product_categories (product_id text REFERENCES products(id) ON DELETE CASCADE, category_id text REFERENCES categories(id) ON DELETE RESTRICT, PRIMARY KEY(product_id,category_id));
CREATE INDEX product_categories_category ON product_categories(category_id,product_id);
CREATE TABLE variants (id text PRIMARY KEY, product_id text NOT NULL REFERENCES products(id) ON DELETE CASCADE, sku text, price bigint NOT NULL CHECK(price>=0), stock integer NOT NULL CHECK(stock>=0), document jsonb NOT NULL);
CREATE UNIQUE INDEX variants_sku ON variants(lower(sku)) WHERE sku IS NOT NULL;
CREATE INDEX variants_product ON variants(product_id);
CREATE TABLE media (id uuid PRIMARY KEY, filename text UNIQUE NOT NULL, mime text NOT NULL, bytes integer NOT NULL, sha256 text NOT NULL, created_by uuid REFERENCES admins(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE customers (id uuid PRIMARY KEY, phone text UNIQUE NOT NULL, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','blocked')), document jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE orders (id uuid PRIMARY KEY, customer_id uuid NOT NULL REFERENCES customers(id), status text NOT NULL CHECK(status IN ('pending','processing','shipped','delivered','cancelled')), total bigint NOT NULL CHECK(total>=0), document jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX orders_customer ON orders(customer_id);
CREATE INDEX orders_status_created ON orders(status,created_at DESC);
CREATE TABLE settings (id text PRIMARY KEY, document jsonb NOT NULL);
CREATE TABLE rate_limits (key text PRIMARY KEY, hits integer NOT NULL, reset_at timestamptz NOT NULL);
CREATE INDEX rate_limits_expiry ON rate_limits(reset_at);
CREATE TABLE audit_log (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, admin_id uuid REFERENCES admins(id), action text NOT NULL, entity_id text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ai_usage (day date PRIMARY KEY, requests integer NOT NULL DEFAULT 0, tokens bigint NOT NULL DEFAULT 0);
